<script setup lang="ts">import{computed,onMounted}from'vue';import DataChart from '@/components/DataChart.vue';import{useDashboardStore}from'@/stores/dashboard';const data=useDashboardStore();onMounted(()=>data.refresh());const couriers=computed(()=>Object.keys(data.summary?.courierVolumes??{})),courierValues=computed(()=>Object.values(data.summary?.courierVolumes??{})),shelves=computed(()=>Object.keys(data.summary?.shelfOccupancy??{})),shelfValues=computed(()=>Object.values(data.summary?.shelfOccupancy??{}))</script>
<template><section class="page"><header class="page-heading"><div><p class="eyebrow">OPERATIONAL INTELLIGENCE</p><h1>数据分析</h1><p>所有图表来自 Java API 当前数据</p></div><button class="ghost" @click="data.refresh">刷新</button></header><div v-if="data.loading&&!data.summary" class="state-panel">正在计算指标…</div><div v-else-if="data.error" class="state-panel error">{{data.error}}</div><div v-else-if="data.summary" class="analytics-grid"><DataChart title="快递公司分布" :labels="couriers" :values="courierValues"/><DataChart title="货架利用率 %" :labels="shelves" :values="shelfValues" color="#ff9b5e"/><article class="chart-card analytics-summary"><p class="eyebrow">DWELL & EXCEPTION</p><strong>{{data.summary.overdue}}</strong><strong>{{data.summary.exceptions}}</strong><strong>{{data.summary.slotUtilization}}%</strong><span>滞留件</span><span>异常件</span><span>总仓位利用率</span></article></div></section></template>
